const https = require('https');
const http  = require('http');
const fs    = require('fs');
const datos = $input.first().json;

// Si el audio ya existe en disco, saltamos la descarga
if (fs.existsSync(datos.audio_path)) {
  console.log(`Audio ya existe: ${datos.audio_path}`);
  return [{ json: datos }];
}

console.log(`Descargando EP${datos.episodio} desde acast...`);

function descargar(url, destino, intentos) {
  return new Promise((resolve, reject) => {
    const proto = url.startsWith('https') ? https : http;
    proto.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        // Seguir redireccion
        descargar(res.headers.location, destino, intentos).then(resolve).catch(reject);
        return;
      }
      if (res.statusCode !== 200) {
        reject(new Error(`HTTP ${res.statusCode} descargando audio`)); return;
      }
      const total = parseInt(res.headers['content-length'] || '0');
      let descargado = 0;
      const archivo = fs.createWriteStream(destino);
      res.on('data', chunk => {
        descargado += chunk.length;
        if (total > 0 && descargado % (1024*1024*50) < chunk.length) {
          console.log(`  ${Math.round(descargado/1024/1024)}MB / ${Math.round(total/1024/1024)}MB`);
        }
      });
      res.pipe(archivo);
      archivo.on('finish', () => { archivo.close(); resolve(); });
      archivo.on('error', (e) => { fs.unlink(destino, ()=>{}); reject(e); });
    }).on('error', (e) => { fs.unlink(destino, ()=>{}); reject(e); });
  });
}

await descargar(datos.audio_url, datos.audio_path, 0);
console.log(`✅ Audio descargado: ${datos.audio_path}`);

return [{ json: datos }];

const { spawn } = require('child_process');
const fs = require('fs');
const datos = $input.first().json;

// Si el video ya existe, saltamos el render
if (fs.existsSync(datos.video_path)) {
  console.log(`Video ya existe: ${datos.video_path}`);
  return [{ json: datos }];
}

console.log(`Creando video con FFmpeg para EP${datos.episodio}...`);
console.log(`Audio: ${datos.audio_path}`);
console.log(`Salida: ${datos.video_path}`);

const resultado = await new Promise((resolve, reject) => {
  const FFMPEG = 'C:\\Users\\Jowy\\AppData\\Local\\Microsoft\\WinGet\\Packages\\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\\ffmpeg-8.0.1-full_build\\bin\\ffmpeg.exe';
  const proc = spawn(FFMPEG, [
    '-y',
    '-ss', '86',
    '-i', datos.audio_path,
    '-f', 'lavfi', '-i', 'color=c=black:size=1920x1080:rate=24',
    '-map', '1:v',
    '-map', '0:a',
    '-c:v', 'libx264',
    '-preset', 'ultrafast',
    '-crf', '28',
    '-c:a', 'aac',
    '-b:a', '128k',
    '-t', '28800',
    datos.video_path
  ]);

  let stderr = '';
  proc.stderr.on('data', d => {
    const linea = d.toString();
    stderr += linea;
    // Mostrar progreso cada vez que FFmpeg reporta tiempo
    if (linea.includes('time=')) {
      const match = linea.match(/time=(\S+)/);
      if (match) process.stdout.write(`\rFFmpeg: ${match[1]}`);
    }
  });

  proc.on('close', (code) => {
    if (code === 0) resolve({ ok: true });
    else reject(new Error(`FFmpeg falló (código ${code}): ${stderr.slice(-300)}`));
  });
});

const sizeMB = Math.round(fs.statSync(datos.video_path).size / 1024 / 1024);
console.log(`\n✅ Video creado: ${datos.video_path} (${sizeMB} MB)`);

return [{ json: datos }];

const fs    = require('fs');
const https = require('https');

const datos   = $('Seleccionar Episodio').first().json;
const response = $input.first().json;
const uploadUrl = response.headers?.location || response.headers?.Location;

if (!uploadUrl) throw new Error('YouTube no devolvió URL de upload.');

const videoPath = datos.video_path;
const fileSize  = fs.statSync(videoPath).size;
console.log(`Subiendo: ${videoPath} (${(fileSize/1024/1024).toFixed(0)} MB)`);

const result = await new Promise((resolve, reject) => {
  const fileStream = fs.createReadStream(videoPath);
  const req = https.request(uploadUrl, {
    method: 'PUT',
    headers: { 'Content-Length': fileSize, 'Content-Type': 'video/mp4' }
  }, (res) => {
    let body = '';
    res.on('data', chunk => body += chunk);
    res.on('end', () => {
      try { resolve(JSON.parse(body)); }
      catch(e) { reject(new Error('Respuesta inválida: ' + body)); }
    });
  });
  req.on('error', reject);
  fileStream.pipe(req);
});

if (!result.id) throw new Error('YouTube no devolvió video ID: ' + JSON.stringify(result));

return [{ json: {
  video_id: result.id,
  url:      `https://www.youtube.com/watch?v=${result.id}`,
  titulo:   result.snippet?.title || datos.titulo,
  status:   result.status?.uploadStatus,
  episodio: datos.episodio
} }];

const datos    = $('Seleccionar Episodio').first().json;
const upload   = $('YouTube - Subir Video').first().json;
const rapidData = $input.first().json;

let tags = [];
try {
  const keywords = rapidData?.generator?.serpKeywords || [];
  const sorted = keywords.sort((a, b) => b.score - a.score);
  let totalChars = 0;
  for (const kw of sorted) {
    const tag = kw.name.trim().replace(/[<>&"#]/g, '');
    if (!tag) continue;
    const cost = tag.length + (tags.length > 0 ? 1 : 0);
    if (totalChars + cost <= 500) { tags.push(tag); totalChars += cost; }
    else break;
  }
  console.log(`RapidTags: ${tags.length} tags (${totalChars} chars)`);
} catch(e) {
  console.log('RapidTags falló:', e.message);
  tags = [datos.keyword];
}

if (tags.length === 0) tags = [datos.keyword];

return [{ json: {
  video_id: upload.video_id,
  body: {
    id: upload.video_id,
    snippet: {
      title:                datos.titulo,
      description:          datos.descripcion,
      tags:                 tags,
      categoryId:           '22',
      defaultLanguage:      'es',
      defaultAudioLanguage: 'es'
    }
  }
} }];

const fs     = require('fs');
const upload = $('YouTube - Subir Video').first().json;
const tags   = $input.first().json;

const log = {
  fecha:             new Date().toISOString(),
  episodio:          upload.episodio,
  video_id:          upload.video_id,
  url:               upload.url,
  titulo:            upload.titulo,
  tags_actualizados: !tags.error,
  status:            upload.status
};

const logPath = 'E:\\RainTube\\logs\\videos_publicados.json';
let logs = [];
try { logs = JSON.parse(fs.readFileSync(logPath, 'utf8')); } catch(e) {}
logs.push(log);
fs.writeFileSync(logPath, JSON.stringify(logs, null, 2));

return [{ json: {
  mensaje:           `✅ Episodio ${upload.episodio} publicado en YouTube`,
  url:               upload.url,
  titulo:            upload.titulo,
  video_id:          upload.video_id,
  tags_actualizados: !tags.error
} }];
